    }
    else if (elapsed < 23000UL) {
      speedDelay = SPEED_8;
    }
    else if (elapsed < 25000UL) {
      speedDelay = SPEED_9;
    }
    else if (elapsed < 27000UL) {
      speedDelay = SPEED_10;
    }
    else if (elapsed < 28000UL) {
      speedDelay = SPEED_11;
    }
    else if (elapsed < 29000UL) {
      speedDelay = SPEED_12;
    }
    else {
      speedDelay = SPEED_13;
    }

    allOff();
    digitalWrite(leds[currentLED], HIGH);

    Serial.print("LED: ");
    Serial.print(colorNames[currentLED]);
    Serial.print(" | SPEED: ");
    Serial.println(speedDelay);

    delay(speedDelay);

